INSERT INTO knowledge_article (company_id, screen_ref, question_zh, question_ms, question_en, answer_zh, answer_ms, answer_en, role_codes) VALUES
(NULL,'C1','忘记 PIN 怎么办','Lupa PIN, apa nak buat','Forgot my PIN','找老板在用户管理重置，新 PIN 会短信发给你。','Minta bos set semula di Pengurusan Pengguna, PIN baru dihantar melalui SMS.','Ask the boss to reset it in User Management. The new PIN is sent by SMS.','{}'),
(NULL,'C4','怎么看一个东西还有多少','Bagaimana nak tengok baki stok','How do I check stock of an item','首页按"查询"，扫条码。','Tekan "Cari" di laman utama, imbas kod bar.','Tap Lookup on the home screen and scan the barcode.','{}'),
(NULL,'W1','送货的来了但没有订单怎么收','Barang sampai tanpa pesanan','Goods arrived without a PO','按"收货"，右下角"无单收货"，照样扫。','Tekan Terima, pilih "Terima tanpa PO" di bawah kanan, imbas seperti biasa.','Tap Receive, then "Receive without PO" at bottom right, and scan as usual.','{WAREHOUSE}'),
(NULL,'W3','一箱有 24 个，我要输 24 还是 1','Sekotak 24 unit, masuk 24 atau 1','A case has 24 units, do I enter 24 or 1','扫箱码时输箱数，扫单个码时输个数。屏幕会写单位。','Imbas kod kotak masuk bilangan kotak; imbas kod unit masuk bilangan unit. Skrin tunjuk unit.','Scan the case barcode and enter cases; scan the unit barcode and enter units. The screen shows the unit.','{WAREHOUSE}'),
(NULL,'W3','到期日怎么选','Bagaimana pilih tarikh luput','How do I pick the expiry date','先选月份，日子默认月底，要改再点。','Pilih bulan dulu, hari lalai hujung bulan, tekan untuk ubah.','Pick the month first. The day defaults to month end; tap to change.','{WAREHOUSE}'),
(NULL,'W4','货坏了怎么办','Barang rosak','Goods are damaged','收货时按"有损坏"，输数量拍照，老板会收到。','Semasa terima tekan "Ada rosak", masuk kuantiti dan ambil gambar. Bos akan dimaklumkan.','While receiving tap "Damaged", enter the qty and take a photo. The boss is notified.','{WAREHOUSE}'),
(NULL,'S1','哪些货架要补','Rak mana perlu diisi','Which shelves need refilling','首页按"补货"，清单最上面最急。','Tekan Isi Semula, yang paling atas paling segera.','Tap Refill. The top of the list is most urgent.','{WAREHOUSE,STOCKER}'),
(NULL,'S3','系统问要不要设为位置，选什么','Sistem tanya set sebagai lokasi, pilih apa','System asks to set as location, what to choose','这个产品以后固定放这里就选"是"。','Jika produk ini akan sentiasa di sini, pilih Ya.','If this product will always live here, choose Yes.','{WAREHOUSE,STOCKER}'),
(NULL,'C8','黄色横条说离线是什么意思','Bar kuning kata luar talian','Yellow bar says offline','没网。照常做，有网自动传。别关 App。','Tiada internet. Teruskan kerja, data dihantar bila ada talian. Jangan tutup App.','No internet. Keep working; data uploads when online. Do not close the app.','{}'),
(NULL,'C8','红色说有记录需要处理','Merah kata ada rekod perlu tindakan','Red says records need attention','点开看原因，改好重传。不会就找老板。','Tekan untuk lihat sebab, betulkan dan hantar semula. Jika tidak pasti, tanya bos.','Tap to see the reason, fix and resend. If unsure, ask the boss.','{}'),
(NULL,'T3','扫不到怎么办','Tidak dapat imbas','Cannot scan','开手电，擦标签。还不行按"打字输入"。','Buka lampu suluh, lap label. Jika masih gagal tekan "Taip".','Turn on the torch and wipe the label. If it still fails, tap Type In.','{}'),
(NULL,'T','按错了怎么退','Tersilap tekan, bagaimana undur','Pressed wrong, how to go back','左上角"返回"，会问你是不是放弃。','Tekan Kembali di atas kiri, sistem akan tanya sama ada mahu batal.','Tap Back at top left. It asks whether to abandon the step.','{}');
